    [900, 1100, 950, 1200].forEach((f, i) => this.tone({ f, to: f * 1.2, dur: 0.08, type: 'triangle', vol: 0.08, delay: i * 0.09 }));
  }
  yawn() {
    this.moo(0.75, 1.4, 0.22);
  }
