    this.add(s, mat, true, o);
  }

  blob(color: THREE.ColorRepresentation, pos: THREE.Vector3, o: Partial<Opts> & { shape?: 'sphere' | 'box'; additive?: boolean } = {}) {
    const mat = new THREE.MeshBasicMaterial({
