      inner.add(mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.1, 6), 0x3d9a3a, 0.02, 0.26, 0));
      inner.rotation.z = Math.PI / 2 - 0.4;
      g.add(inner);
      break;
    }
  }
