+  // ───────────────────────── ball ─────────────────────────
+
+  private togglePlay() {
+    if (!this.started) return;
+    if (this.ball) {
+      this.scene.remove(this.ball.mesh);
+      this.ball = null;
+      if (this.act.kind === 'chase') this.act = this.idle();
