+      if (this.ball) this.togglePlay();
+      this.say(this.stats.clean < 50 ? 'Bath time? Okay…' : "I'm already clean!", 1.8);
+    } else if (this.scrubbed >= 8 && !this.save.asleep) {
+      this.act = { kind: 'shake', t: 0 };
