+  }
+
+  private wake(grumpy: boolean) {
+    this.save.asleep = false;
+    this.cow.lieTarget = 0;
+    this.sleepBoops = [];
+    this.ui.setModes({ wash: this.washMode, asleep: false, ball: !!this.ball });
