+
+  // ───────────────────────── reactions ─────────────────────────
+
+  private react(style: ReactStyle) {
+    const dur: Record<ReactStyle, number> = {
+      love: 1.3,
+      like: 0.9,
+      hot: 2.6,
+      crave: 1.9,
+      ache: 2.2,
+      refuse: 1.0,
+      boop: 0.6,
+      giggle: 1.4,
+      yawn: 1.7,
+      levelup: 1.6,
+      grumpy: 1.4,
+      sing: 2.2,
+    };
+    this.act = { kind: 'react', style, t: 0, dur: dur[style], origin: this.cow.root.position.clone() };
+    const head = this.headPos();
+    switch (style) {
+      case 'love':
+        this.cow.hop(4.5);
+        this.particles.hearts(head, 6);
+        this.sfx.heart();
+        this.sfx.moo(1.3, 0.6);
+        break;
+      case 'like':
+        this.particles.hearts(head, 2);
+        this.sfx.moo(1.15, 0.45, 0.22);
+        break;
+      case 'hot':
+        this.sfx.hot();
+        this.cow.hop(6);
+        break;
+      case 'crave':
+        this.cow.spin(1.1, 1);
+        this.cow.hop(6);
+        this.particles.confetti(head, 28);
+        this.particles.hearts(head, 8);
+        this.sfx.sparkle();
+        this.sfx.moo(1.4, 0.7);
+        break;
+      case 'ache':
+        this.sfx.yuck();
+        break;
+      case 'refuse':
+        this.cow.shake(0.8);
+        this.sfx.yuck();
+        break;
+      case 'boop':
+        break;
+      case 'giggle':
+        this.cow.spin(0.9, Math.random() < 0.5 ? 1 : -1);
+        this.cow.hop(4);
+        this.sfx.giggle();
+        this.particles.hearts(head, 4);
+        break;
+      case 'yawn':
+        this.sfx.yawn();
+        break;
+      case 'levelup':
+        this.cow.spin(1.2, 1);
+        this.cow.hop(6);
+        this.particles.sparkles(head, 12);
+        break;
+      case 'grumpy':
+        this.sfx.moo(0.8, 0.6, 0.2);
+        break;
+      case 'sing':
+        this.sfx.moo(1.2, 0.5, 0.2);
+        setTimeout(() => this.sfx.moo(1.45, 0.5, 0.2), 550);
