+    this.sfx.bell();
+    this.particles.hearts(head, 1);
+    if (this.boopTimes.length === 1) {
+      this.bump('happy', 2);
+      this.addXp(1);
+    }
+    if (INTERRUPTIBLE.has(this.act.kind)) this.act = this.idle(r(1.5, 3));
+    if (Math.random() < 0.6) this.say(pick(['Moo!', 'Moo?', 'Boop!', 'Hi hi!', 'Mooo~']), 1.2);
