.intro p {
  margin: 0 0 16px;
  color: var(--ink-soft);
  font-size: 15px;
  line-height: 1.45;
}

.intro ul {
  list-style: none;
  padding: 0;
  margin: 0 0 20px;
  display: grid;
  gap: 8px;
  text-align: left;
}

.intro li {
  background: #fff;
  border-radius: 14px;
  padding: 9px 12px;
  font-size: 14px;
  color: var(--ink-soft);
  box-shadow: 0 2px 0 #f1e6df;
}

.intro li b {
  color: var(--ink);
  font-weight: 600;
  margin-right: 4px;
}

.primary {
  width: 100%;
  padding: 14px;
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  border-radius: 18px;
  background: linear-gradient(160deg, #ff9fbd, var(--pink));
  box-shadow: 0 5px 0 var(--pink-deep), 0 10px 24px rgba(255, 122, 162, 0.4);
  transition: transform 0.12s, box-shadow 0.12s;
}

.primary:hover {
  transform: translateY(-2px);
}

.primary:active {
  transform: translateY(4px);
  box-shadow: 0 1px 0 var(--pink-deep);
}

/* ───── animations ───── */

@keyframes bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

@keyframes wiggle {
  0%,
  100% {
    transform: rotate(0);
  }
  25% {
    transform: rotate(-10deg);
  }
  75% {
    transform: rotate(10deg);
  }
}

@keyframes pulse {
  50% {
    opacity: 0.55;
  }
}

@keyframes rise {
  0% {
    opacity: 0;
    transform: translateY(8px) scale(0.7);
  }
  15% {
    opacity: 1;
    transform: translateY(0) scale(1.05);
  }
  100% {
    opacity: 0;
    transform: translateY(-70px) scale(1);
  }
}

@keyframes drop {
  from {
    opacity: 0;
    transform: translateY(-14px) scale(0.9);
  }
}

/* ───── small screens ───── */

@media (max-width: 720px) {
  .topbar {
    left: 14px;
    right: 14px;
  }
  .status {
    left: 10px;
    right: 10px;
    width: auto;
    padding: 10px 12px;
    border-radius: 20px;
  }
  .id-row {
    display: none;
  }
  .xp {
    margin: 0 0 6px;
  }
  .mood {
    margin-bottom: 6px;
    font-size: 13px;
  }
  .stats {
    grid-template-columns: 1fr 1fr;
    gap: 6px 12px;
  }
  .stat-ic {
    width: 24px;
    height: 24px;
    font-size: 14px;
  }
  .foot {
    display: none;
  }
  .dock button {
    width: 66px;
    height: 60px;
  }
  .dock .ic {
    font-size: 22px;
  }
  #ui .chip {
    width: 60px;
  }
  .chip-meta {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
  }
}

