import { chromium } from 'playwright-core';
import { mkdirSync } from 'node:fs';

const out = new URL('../.shots/', import.meta.url).pathname;
mkdirSync(out, { recursive: true });
const url = 'http://localhost:9366/';
const w = Number(process.env.W ?? 1440);
const h = Number(process.env.H ?? 900);

const browser = await chromium.launch({ channel: 'chrome', args: ['--use-angle=metal', '--enable-gpu'] });
const page = await browser.newPage({ viewport: { width: w, height: h } });
const errors = [];
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto(url);
await page.waitForTimeout(1500);
await page.screenshot({ path: out + '1-intro.png' });
await page.click('#start');
await page.waitForTimeout(1800);
await page.screenshot({ path: out + '2-hi.png' });

const head = () =>
  page.evaluate(() => {
    const g = window.__game;
    const v = g.cow.mouthWorld(new g.camera.position.constructor()).project(g.camera);
    return { x: (v.x * 0.5 + 0.5) * innerWidth, y: (-v.y * 0.5 + 0.5) * innerHeight };
  });

await page.click('[data-act="feed"]');
await page.waitForTimeout(500);
await page.screenshot({ path: out + '3-tray.png' });

const chip = await page.locator('[data-food="apple"]').boundingBox();
const m = await head();
await page.mouse.move(chip.x + chip.width / 2, chip.y + chip.height / 2);
await page.mouse.down();
for (let i = 1; i <= 25; i++) {
  await page.mouse.move(chip.x + (m.x - chip.x) * (i / 25), chip.y + (m.y + 10 - chip.y) * (i / 25));
  await page.waitForTimeout(30);
}
await page.waitForTimeout(250);
await page.screenshot({ path: out + '4-lure.png' });
for (let i = 0; i < 20; i++) {
  const mm = await head();
  await page.mouse.move(mm.x, mm.y);
  await page.waitForTimeout(60);
}
await page.screenshot({ path: out + '5-snatch.png' });
await page.mouse.up();
await page.waitForTimeout(700);
await page.screenshot({ path: out + '6-eat.png' });
await page.waitForTimeout(1200);
await page.screenshot({ path: out + '7-react.png' });

const chili = await page.locator('[data-food="chili"]').boundingBox();
await page.mouse.click(chili.x + chili.width / 2, chili.y + chili.height / 2);
await page.waitForTimeout(3200);
await page.screenshot({ path: out + '8-chili.png' });

const state = await page.evaluate(() => ({ act: window.__game.act.kind, stats: window.__game.save.stats, fed: window.__game.save.fed, xp: window.__game.save.xp }));
console.log(JSON.stringify(state));

await page.click('[data-act="play"]');
await page.waitForTimeout(2500);
await page.screenshot({ path: out + '9-play.png' });
await page.click('[data-act="play"]');

await page.evaluate(() => {
  const g = window.__game;
  g.save.stats.energy = 40;
  g.save.stats.clean = 20;
});
await page.click('[data-act="sleep"]');
await page.waitForTimeout(3000);
await page.screenshot({ path: out + '10-sleep.png' });

console.log('errors:', JSON.stringify(errors));
await browser.close();

