import { chromium } from 'playwright-core';

const browser = await chromium.launch({ channel: 'chrome' });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:9366/');
await page.waitForTimeout(1000);
await page.click('#start');
await page.waitForTimeout(500);
await page.click('[data-act="feed"]');
await page.waitForTimeout(400);

const probe = () =>
  page.evaluate(() => {
    const g = window.__game;
    const V = g.camera.position.constructor;
    const m = g.cow.mouthWorld(new V());
    const s = m.clone().project(g.camera);
    return {
      act: g.act.kind,
      held: g.held ? { state: g.held.state, vis: g.held.mesh.visible, pos: g.held.pos.toArray().map((n) => +n.toFixed(2)) } : null,
      mouth: m.toArray().map((n) => +n.toFixed(2)),
      d: g.held ? +m.distanceTo(g.held.pos).toFixed(2) : null,
      scr: { x: (s.x * 0.5 + 0.5) * innerWidth, y: (-s.y * 0.5 + 0.5) * innerHeight },
      foods: g.foods.map((f) => f.state),
      fed: g.save.fed,
    };
  });

const chip = await page.locator('[data-food="apple"]').boundingBox();
let p = await probe();
await page.mouse.move(chip.x + 30, chip.y + 30);
await page.mouse.down();
await page.mouse.move(chip.x + 30, chip.y + 10, { steps: 3 });
for (let i = 0; i < 30; i++) {
  p = await probe();
  await page.mouse.move(p.scr.x, p.scr.y, { steps: 2 });
  if (i % 5 === 0) console.log(JSON.stringify(p));
  await page.waitForTimeout(50);
}
await page.mouse.up();
await page.waitForTimeout(1600);
console.log('after', JSON.stringify(await probe()));

const chili = await page.locator('[data-food="chili"]').boundingBox();
await page.mouse.click(chili.x + 30, chili.y + 30);
for (let i = 0; i < 6; i++) {
  await page.waitForTimeout(700);
  console.log('toss', JSON.stringify(await probe()));
}
await browser.close();

