  border-radius: 18px;
  font-size: 16px;
  font-weight: 600;
  white-space: nowrap;
  box-shadow: var(--shadow);
  opacity: 0;
  translate: -50% -100%;
  scale: 0.6;
  transition: opacity 0.18s ease, scale 0.25s cubic-bezier(0.3, 1.6, 0.5, 1);
}

.speech::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: #fff;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 3px;
}

.speech.show {
  opacity: 1;
  scale: 1;
}

.thought {
  width: 56px;
  height: 56px;
  display: grid;
  place-items: center;
  background: #fff;
  border-radius: 50%;
  font-size: 28px;
  box-shadow: var(--shadow);
  translate: -50% -100%;
  opacity: 0;
  scale: 0.4;
  transition: opacity 0.3s ease, scale 0.35s cubic-bezier(0.3, 1.6, 0.5, 1);
}

.thought::before,
.thought::after {
  content: '';
  position: absolute;
  background: #fff;
  border-radius: 50%;
  box-shadow: var(--shadow);
}

.thought::before {
  width: 14px;
  height: 14px;
  left: -2px;
  bottom: -6px;
}

.thought::after {
  width: 8px;
  height: 8px;
  left: -12px;
  bottom: -16px;
}

.thought.show {
  opacity: 1;
  scale: 1;
}

.thought span {
  animation: bob 1.8s ease-in-out infinite;
}

body.dragging .thought,
.speech.show ~ .thought {
  opacity: 0;
}

/* ───── floaters & toasts ───── */

.floater {
  position: absolute;
  translate: -50% 0;
  font-weight: 700;
  font-size: 15px;
  white-space: nowrap;
  padding: 2px 10px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 4px 12px rgba(58, 46, 57, 0.15);
  animation: rise 1.6s ease-out forwards;
}

.floater.good {
  color: #2f9e44;
}
.floater.bad {
  color: #e03131;
}
.floater.xp {
  color: #845ef7;
}

.toasts {
  position: absolute;
  top: calc(max(16px, env(safe-area-inset-top)) + 4px);
  left: 50%;
  translate: -50% 0;
  display: grid;
  gap: 8px;
  justify-items: center;
  width: min(90vw, 440px);
}

.toast {
  padding: 10px 18px;
  border-radius: 16px;
  background: rgba(58, 46, 57, 0.88);
  color: #fff;
  font-size: 14px;
  font-weight: 500;
  box-shadow: var(--shadow);
  animation: drop 0.35s cubic-bezier(0.3, 1.5, 0.5, 1);
  transition: opacity 0.4s, transform 0.4s;
  text-align: center;
}

.toast.party {
  background: linear-gradient(90deg, #b892ff, #ff7aa2);
  font-weight: 600;
}

.toast.warn {
  background: #e8590c;
}

.toast.out {
  opacity: 0;
  transform: translateY(-10px);
}

/* ───── bottom: tray + dock ───── */

.bottom {
  position: absolute;
  left: 50%;
  bottom: max(18px, env(safe-area-inset-bottom));
  translate: -50% 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: max-content;
  max-width: calc(100vw - 24px);
}

.tray {
  pointer-events: none;
  opacity: 0;
  transform: translateY(16px) scale(0.96);
  transition: opacity 0.2s ease, transform 0.28s cubic-bezier(0.3, 1.4, 0.5, 1);
  background: var(--card);
  border: 1px solid var(--card-edge);
  border-radius: 24px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  padding: 10px 12px 12px;
}

#ui .tray.open {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

#ui .tray.open .chip {
  pointer-events: auto;
}

body.dragging #ui .tray.open {
  opacity: 0.35;
  transform: translateY(8px) scale(0.97);
}

.tray-hint {
  margin: 0 0 8px;
  text-align: center;
  font-size: 12.5px;
  color: var(--ink-soft);
  font-weight: 500;
}

.foods {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
}

#ui .chip {
  pointer-events: none;
  position: relative;
  width: 72px;
  flex: none;
  padding: 8px 4px 7px;
  border-radius: 18px;
  background: #fff;
  box-shadow: 0 3px 0 #eadfd8, 0 6px 14px rgba(58, 46, 57, 0.08);
  display: grid;
  justify-items: center;
  gap: 1px;
  touch-action: none;
  cursor: grab;
  transition: transform 0.15s cubic-bezier(0.3, 1.6, 0.5, 1), box-shadow 0.15s;
}

.tray.open .chip:hover {
  transform: translateY(-4px) rotate(-2deg);
}

.chip:active {
  transform: translateY(2px) scale(0.96);
  box-shadow: 0 1px 0 #eadfd8;
}

.chip-emoji {
  font-size: 30px;
  line-height: 1.1;
  filter: drop-shadow(0 2px 2px rgba(0, 0, 0, 0.12));
}

.chip-name {
  font-size: 12.5px;
  font-weight: 600;
}

.chip-meta {
  font-size: 10px;
  color: var(--ink-soft);
}

.crave-badge {
  position: absolute;
  top: -9px;
  left: 50%;
  translate: -50% 0;
  padding: 1px 7px;
  font-size: 10px;
  font-weight: 700;
  border-radius: 99px;
  background: var(--pink);
  color: #fff;
  white-space: nowrap;
  opacity: 0;
  scale: 0.5;
  transition: opacity 0.2s, scale 0.3s cubic-bezier(0.3, 1.6, 0.5, 1);
}

.chip.craved {
  box-shadow: 0 3px 0 #ffb3c9, 0 0 0 2.5px var(--pink), 0 8px 18px rgba(255, 122, 162, 0.35);
}

.chip.craved .crave-badge {
  opacity: 1;
  scale: 1;
}

.chip.craved .chip-emoji {
  animation: wiggle 1s ease-in-out infinite;
}

.mode-hint {
  font-size: 13px;
  font-weight: 500;
  color: #fff;
  background: rgba(58, 46, 57, 0.6);
  padding: 6px 14px;
  border-radius: 99px;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.25s, transform 0.25s;
  height: 0;
  padding-top: 0;
  padding-bottom: 0;
  overflow: hidden;
}

.mode-hint.show {
  opacity: 1;
  transform: none;
  height: auto;
  padding: 6px 14px;
}

.dock {
  display: flex;
  gap: 10px;
  padding: 10px;
  border-radius: 28px;
  background: var(--card);
  border: 1px solid var(--card-edge);
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.dock button {
  width: 78px;
  height: 70px;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 4px 0 #eadfd8, 0 6px 14px rgba(58, 46, 57, 0.08);
  display: grid;
  place-items: center;
  align-content: center;
  gap: 2px;
  transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.2s;
}

.dock button:hover {
  transform: translateY(-2px);
}

.dock button:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #eadfd8;
}

.dock .ic {
  font-size: 26px;
  line-height: 1;
}

.dock .lbl {
  font-size: 13px;
  font-weight: 600;
}

.dock button.active {
  background: linear-gradient(160deg, #ff9fbd, var(--pink));
  color: #fff;
  box-shadow: 0 4px 0 var(--pink-deep), 0 8px 18px rgba(255, 122, 162, 0.35);
}

body.asleep .title {
  color: #fff3c4;
}

/* ───── intro ───── */

.intro {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at center, rgba(255, 240, 246, 0.35), rgba(58, 46, 57, 0.35));
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
  padding: 20px;
}

.intro.show {
  opacity: 1;
  pointer-events: auto;
}

.intro-card {
  width: min(400px, 100%);
  background: #fffaf6;
  border-radius: 30px;
  padding: 28px 26px 24px;
  text-align: center;
  box-shadow: 0 30px 80px rgba(58, 46, 57, 0.35);
  transform: translateY(20px) scale(0.95);
  transition: transform 0.45s cubic-bezier(0.3, 1.5, 0.5, 1);
}

.intro.show .intro-card {
  transform: none;
}

.intro-cow {
  font-size: 64px;
  line-height: 1;
  animation: bob 2s ease-in-out infinite;
}

.intro h2 {
  margin: 8px 0 6px;
  font-size: 28px;
}

.intro p {
  margin: 0 0 16px;
  color: var(--ink-soft);
  font-size: 15px;
  line-height: 1.45;
}

.intro ul {
  list-style: none;
  padding: 0;
  margin: 0 0 20px;
  display: grid;
  gap: 8px;
  text-align: left;
}

.intro li {
  background: #fff;
  border-radius: 14px;
  padding: 9px 12px;
  font-size: 14px;
  color: var(--ink-soft);
  box-shadow: 0 2px 0 #f1e6df;
}

.intro li b {
  color: var(--ink);
  font-weight: 600;
  margin-right: 4px;
}

.primary {
  width: 100%;
  padding: 14px;
  font-size: 18px;
  font-weight: 700;
  color: #fff;
  border-radius: 18px;
  background: linear-gradient(160deg, #ff9fbd, var(--pink));
  box-shadow: 0 5px 0 var(--pink-deep), 0 10px 24px rgba(255, 122, 162, 0.4);
  transition: transform 0.12s, box-shadow 0.12s;
}

.primary:hover {
  transform: translateY(-2px);
}

.primary:active {
  transform: translateY(4px);
  box-shadow: 0 1px 0 var(--pink-deep);
}

/* ───── animations ───── */

@keyframes bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

@keyframes wiggle {
  0%,
  100% {
    transform: rotate(0);
  }
  25% {
    transform: rotate(-10deg);
  }
  75% {
    transform: rotate(10deg);
  }
}

@keyframes pulse {
  50% {
    opacity: 0.55;
  }
}

@keyframes rise {
  0% {
    opacity: 0;
    transform: translateY(8px) scale(0.7);
  }
  15% {
    opacity: 1;
    transform: translateY(0) scale(1.05);
  }
  100% {
    opacity: 0;
    transform: translateY(-70px) scale(1);
  }
}

@keyframes drop {
  from {
    opacity: 0;
    transform: translateY(-14px) scale(0.9);
  }
}

/* ───── small screens ───── */

@media (max-width: 720px) {
  .topbar {
    left: 14px;
    right: 14px;
  }
  .status {
    left: 10px;
    right: 10px;
    width: auto;
    padding: 10px 12px;
    border-radius: 20px;
  }
  .id-row {
    display: none;
  }
  .xp {
    margin: 0 0 6px;
  }
  .mood {
    margin-bottom: 6px;
    font-size: 13px;
  }
  .stats {
    grid-template-columns: 1fr 1fr;
    gap: 6px 12px;
  }
  .stat-ic {
    width: 24px;
    height: 24px;
    font-size: 14px;
  }
  .foot {
    display: none;
  }
  .dock button {
    width: 66px;
    height: 60px;
  }
  .dock .ic {
    font-size: 22px;
  }
  #ui .chip {
    width: 60px;
  }
  .chip-meta {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
  }
}

