import { chromium } from 'playwright-core';

const out = new URL('../.shots/', import.meta.url).pathname;
const browser = await chromium.launch({ channel: 'chrome' });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://localhost:9366/');
await page.waitForTimeout(1200);
await page.screenshot({ path: out + 'm1-intro.png' });
await page.click('#start');
await page.waitForTimeout(1200);
await page.click('[data-act="feed"]');
await page.evaluate(() => {
  const g = window.__game;
  g.save.stats.clean = 15;
  g.spawnPoopMesh(1.5, 1);
  g.craving = 'clover';
  g.ui.setCraving('clover');
});
await page.waitForTimeout(1500);
await page.screenshot({ path: out + 'm2-tray.png' });
console.log('errors', JSON.stringify(errors));
await browser.close();

