  display: grid;
  place-items: center;
  font-size: 17px;
  background: rgba(255, 255, 255, 0.8);
  border-radius: 10px;
  box-shadow: 0 1px 0 rgba(58, 46, 57, 0.08);
}

.stat-main {
  flex: 1;
}

.stat-top {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 3px;
}

.stat-val {
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.bar {
  height: 9px;
  background: rgba(58, 46, 57, 0.08);
