import { chromium } from 'playwright-core';

const out = new URL('../.shots/', import.meta.url).pathname;
const browser = await chromium.launch({ channel: 'chrome' });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://localhost:9366/');
await page.waitForTimeout(800);
await page.click('#start');
await page.waitForTimeout(2500);

const cowCenter = () =>
  page.evaluate(() => {
    const g = window.__game;
    const V = g.camera.position.constructor;
    const p = g.cow.root.position.clone().add(new V(0, 0.8 * g.cow.scale, 0.2)).project(g.camera);
    return { x: (p.x * 0.5 + 0.5) * innerWidth, y: (-p.y * 0.5 + 0.5) * innerHeight };
  });
const stats = () => page.evaluate(() => ({ ...window.__game.save.stats, act: window.__game.act.kind, wash: window.__game.washMode, poops: window.__game.poops.length }));

await page.evaluate(() => {
  const g = window.__game;
  g.save.stats.clean = 40;
  g.save.stats.happy = 40;
  g.act = { kind: 'idle', t: 30 };
});
console.log('before', JSON.stringify(await stats()));

await page.click('[data-act="wash"]');
let c = await cowCenter();
await page.mouse.move(c.x - 40, c.y);
await page.mouse.down();
for (let i = 0; i < 30; i++) {
  await page.mouse.move(c.x + (i % 2 ? 40 : -40), c.y + (i % 3) * 8, { steps: 4 });
}
await page.screenshot({ path: out + 'c1-scrub.png' });
await page.mouse.up();
console.log('after scrub', JSON.stringify(await stats()));
if ((await stats()).wash) await page.click('[data-act="wash"]');
await page.waitForTimeout(600);
await page.screenshot({ path: out + 'c2-shake.png' });
await page.waitForTimeout(1200);

await page.evaluate(() => (window.__game.act = { kind: 'idle', t: 30 }));
c = await cowCenter();
await page.mouse.move(c.x - 40, c.y);
await page.mouse.down();
for (let i = 0; i < 16; i++) await page.mouse.move(c.x + (i % 2 ? 40 : -40), c.y, { steps: 4 });
await page.screenshot({ path: out + 'c3-pet.png' });
await page.mouse.up();
console.log('after pet', JSON.stringify(await stats()));

for (let i = 0; i < 5; i++) {
  c = await cowCenter();
  await page.mouse.click(c.x, c.y);
  await page.waitForTimeout(120);
}
await page.waitForTimeout(300);
console.log('after boops', JSON.stringify(await stats()));
await page.screenshot({ path: out + 'c4-giggle.png' });

const pp = await page.evaluate(() => {
  const g = window.__game;
  const p = g.spawnPoopMesh(-2, 1.5);
  const V = g.camera.position.constructor;
  const s = new V(p.x, 0.2, p.z).project(g.camera);
  return { x: (s.x * 0.5 + 0.5) * innerWidth, y: (-s.y * 0.5 + 0.5) * innerHeight };
});
await page.waitForTimeout(300);
await page.mouse.click(pp.x, pp.y);
await page.waitForTimeout(300);
console.log('after poop click', JSON.stringify(await stats()));
console.log('errors', JSON.stringify(errors));
await browser.close();

